BEGIN;

-- Pages 76-90 of the 10th revised edition (#173): «أذكار المسجد» (pp76-78)
-- and «أذكار الأذان» (pp79-90), compared page by page with the book.
-- * the book prints no grade under any of these dhikr, so `hokm` is empty;
--   `source` keeps the heading, the printed bracket and the page as printed
--   (the 1443 edition's pp39-48 are gone), and the footnotes after «حاشية:»;
-- * «أذكار المسجد» follows the book's five headings, each a section of its
--   own under category 108 (renamed to the book's chapter heading): title 8
--   is «ما يقول إذا توجَّه إلى المسجد», and the new titles 167, 168, 169
--   hold the entering, lost-property and leaving dhikr, so «ما يقول في
--   المسجد» (109) stands between entering and lost property as printed;
-- * «باسم الله» as printed (not «بسم الله»), «أو:» kept before the printed
--   alternatives, «ويمكن أن يزيد:» and the selling line are passages of
--   their own; the app's own wording in the sources is removed;
-- * «أذكار الأذان» (9) is the book's text under its headings: the adhan in
--   its printed steps with the counts [مرَّتين] and [أربعًا], the tathwib,
--   the rainy night, the iqama as printed line by line, and what the listener
--   says, with the instructions between the dhikr as passages (count 0);
--   «يكثر الدعاء بين الأذان والإقامة» is the printed sentence, not a dhikr
--   with a virtue line; «وقال رجل: يا رسول الله…» (p89) is added;
-- * «ما يقول الإمام للمصلين بين يدي الصلاة» (114) gains «أو أيًّا من الوصايا
--   التالية:» and reads «لِيَلِيَنِي» as printed.
-- The rows below are written from data_pipeline/sections/*.json.

DELETE FROM contents WHERE titleId IN (8, 9, 109, 114);
UPDATE titles SET name = 'أذكار المسجد' WHERE id = 108;
UPDATE titles SET name = 'ما يقول إذا توجَّه إلى المسجد' WHERE id = 8;
UPDATE titles SET "order" = 3 WHERE id = 109;
