INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1528, 8, 1, 'يقول ما تقدَّم في: (ما يقول إذا خَرَجَ من بيته)، ويَزِيد:', 0, 'ما يقول إذا توجَّه إلى المسجد. (ص76)

حاشية: تقدَّم (ص٧٤).', '', '', 'يقول ما تقدم في ما يقول إذا خرج من بيته ويزيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (75, 8, 2, 'اللهم اجعل في قلبي نورًا، وفي لساني نورًا، واجعل في سمعي نورًا، واجعل في بصري نورًا، واجعل مِن خلفي نورًا، ومن أمامي نورًا، واجعل من فوقي نورًا، ومن تحتي نورًا، اللهم أعطِني نورًا', 1, 'ما يقول إذا توجَّه إلى المسجد. (ص76)', '', '', 'اللهم اجعل في قلبي نورا وفي لساني نورا واجعل في سمعي نورا واجعل في بصري نورا واجعل من خلفي نورا ومن أمامي نورا واجعل من فوقي نورا ومن تحتي نورا اللهم أعطني نورا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (76, 167, 1, 'أعوذُ باللهِ العظيمِ، وبوجهِهِ الكريمِ، وسُلْطانِهِ القديمِ من الشيطانِ الرجيم', 1, 'ما يقول عند دخول المسجد. (ص76)', '', '', 'أعوذ بالله العظيم وبوجهه الكريم وسلطانه القديم من الشيطان الرجيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (77, 167, 2, 'باسمِ الله، اللهم صَلِّ على محمدٍ وآلِهِ وسَلِّم، اللهم افتَحْ لي أبوابَ رحمتِكَ', 1, 'ما يقول عند دخول المسجد. (ص77)', '', '', 'باسم الله اللهم صل على محمد وآله وسلم اللهم افتح لي أبواب رحمتك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1010, 109, 1, 'يُستَحَبُّ فيه الإكثارُ من ذكر الله تعالى، والتسبيح، والتهليل، والتحميد، والتكبير، والاستغفار، والدعاء، وغيرها من الأذكار المطلقة.', 0, 'ما يقول في المسجد. (ص77)

حاشية: انظر: «الأذكار المطلقة» (ص٢٤٧)، وما بعدها، و«الأدعية المطلقة» (ص٣٨١)، وما بعدها.', '', '', 'يستحب فيه الإكثار من ذكر الله تعالى والتسبيح والتهليل والتحميد والتكبير والاستغفار والدعاء وغيرها من الأذكار المطلقة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1529, 109, 2, 'ويُسْتَحَبُّ الإكثارُ من قراءة القرآن الكريم، وقراءة حديث رسول الله ﷺ، وعلمِ الفقه، وسائرِ العلوم الشرعية.', 0, 'ما يقول في المسجد. (ص77)', '', '', 'ويستحب الإكثار من قراءة القرآن الكريم وقراءة حديث رسول الله وعلم الفقه وسائر العلوم الشرعية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (78, 168, 1, 'لا رَدَّ اللهُ عليكَ ضالَّتَكَ', 1, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص77)', '', '', 'لا رد الله عليك ضالتك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (79, 168, 2, 'أو: لا رَدَّها اللهُ عليكَ', 1, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص77)', '', '', 'أو لا ردها الله عليك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1530, 168, 3, 'ويمكن أن يَزِيدَ:', 0, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص78)', '', '', 'ويمكن أن يزيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (80, 168, 4, 'فإنَّ المساجِدَ لم تُبْنَ لهذا', 1, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص78)', '', '', 'فإن المساجد لم تبن لهذا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (81, 168, 5, 'أو: لا وَجَدْتَ', 1, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص78)', '', '', 'أو لا وجدت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1531, 168, 6, 'ويمكن أن يزيد:', 0, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص78)', '', '', 'ويمكن أن يزيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (892, 168, 7, 'إنَّما بُنِيَتْ المساجِدُ لما بُنِيَتْ له', 1, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص78)', '', '', 'إنما بنيت المساجد لما بنيت له', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1532, 168, 8, 'وإذا رأى من يبيع، أو يبتاع –أي: يشتري– في المسجد، قال:', 0, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص78)', '', '', 'وإذا رأى من يبيع أو يبتاع –أي يشتري– في المسجد قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (893, 168, 9, 'لا أَرْبَحَ اللهُ تجارتَك', 1, 'ما يقول إذا سمع من ينشد ضالة في المسجد. (ص78)', '', '', 'لا أربح الله تجارتك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (894, 169, 1, 'باسم الله، اللهمَّ صَلِّ على محمدٍ وآلِهِ وسَلِّمْ، اللهمَّ إنِّي أسألُكَ مِن فَضْلِكَ', 1, 'ما يقول عند الخروج من المسجد. (ص78)', '', '', 'باسم الله اللهم صل على محمد وآله وسلم اللهم إني أسألك من فضلك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (895, 169, 2, 'اللهم اعصِمْني من الشيطان الرجيم', 1, 'ما يقول عند الخروج من المسجد. (ص78)', '', '', 'اللهم اعصمني من الشيطان الرجيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (896, 169, 3, 'أو: اللهم أعِذْني من الشيطان الرجيم', 1, 'ما يقول عند الخروج من المسجد. (ص78)', '', '', 'أو اللهم أعذني من الشيطان الرجيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (897, 169, 4, 'أو: اللهم أَجِرْني من الشيطان الرجيم', 1, 'ما يقول عند الخروج من المسجد. (ص78)', '', '', 'أو اللهم أجرني من الشيطان الرجيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1533, 9, 1, 'يقول المؤذِّنُ بتَرَسُّلٍ:', 0, 'صفة الأذان. (ص79)

حاشية: أي بتمهُّلٍ وتُؤَدَةٍ وتحقيقٍ لألفاظِ الأذان، من غير عجلةٍ ولا تمطيطٍ ولا مَدٍّ مُفْرِطٍ.', '', '', 'يقول المؤذن بترسل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (82, 9, 2, 'اللهُ أكبرَ، اللهُ أكبرْ', 2, 'صفة الأذان. [مرَّتين في نَفَسٍ واحدٍ]. (ص79)', '', '', 'الله أكبر الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1534, 9, 3, 'أو: «اللهُ أكبرْ»', 4, 'صفة الأذان. [أربعًا]. (ص79)

حاشية: قال الإمام النووي رحمه الله: «يستحبُّ للمؤذِّنِ أن يقولَ كلَّ تكبيرتين بنَفَسٍ واحدٍ، فيقول في أوَّلِ الأذان (الله أكبرَ، اللهُ أكبرْ)، ثُمَّ يقول: (اللهُ أكبرَ، الله أكبرْ) بِنَفَسٍ آخرَ».اهـ. من «شرح النووي» (٤/ ٧٩)، ودليل ما قاله النووي حديثُ عمر رضي الله عنه مرفوعًا: «إذا قال المؤذِّن: الله أكبر، الله أكبر. فقال أحدكم: الله أكبر، الله أكبر...» الحديث. [رواه مسلم (٣٨٥)]
وإذا وصل المؤذن التكبيرتين؛ يفتحُ الراءَ في التكبيرةِ الأولى.
وذكروا أنَّ الأصل في الراء الأولى الضم، ثُمَّ سُكِّنَت للوقف، ثُمَّ نُقِلَتْ حركةُ همزة وصل (أل) التعريف المفتوحة إليها، فصارت مفتوحةً، وهذا بتعبير النحويين: وصلٌ بنية الوقف، فهي تُنطَقُ في الأذان والإقامة مفتوحة، وهي السُّنَّة.
وقيل: المؤذِّن مُخَيَّرٌ بنطقها بين الفتح والضم.. قال الحنفية: «يُكَبِّرُ في أوَّلِه أربعًا، وَيُسَكِّنُ راءَ (أكبر) الأولى، أو يصلها بـ(الله أكبر) الثانية، وينوي السكون، ويحرِّكُ الراءَ بالفتحة، فإنْ ضمَّ خالفَ السُّنَّة».
ونقل الشربيني عن الهروي قال: «وعوامُّ النَّاسِ يضمُّونَ الرَّاءَ من قوله (الله أكبر) وكان المبرد يفتح الراء، ويقول: (اللهُ أكبرَ، الله أكبرْ)، فيفتحها في الكلمة الأولى، ويقف في الثانية».اهـ. من «مغني المحتاج» (١/ ١٩٠).
وقال ابن عابدين: «إنْ وَصَلَها؛ نَوَى السكونَ، فحرَّكَ الراء بالفتحة، فإنْ ضمَّها خالفَ السُّنَّة».اهـ. من «رد المحتار» (١/ ٣٨٦)، يعني لأنَّ طلبَ الوقف على (أكبر) الأُولَى؛ صَيَّرَه كالساكنِ، فَحُرِّكَ بالفتح.
وعن إبراهيم النَّخَعي، قال: «الأذان جَزْمٌ، والإقامة جزم، والتكبير جزم»، ومعنى قوله: «الأذان جَزْمٌ» أنه مقطوعُ المدِّ بعد همزةِ الوصل، فلا تَقُلْ: «آلله أكبر»؛ لأنَّه استفهام، وهو لحن.
أو: مقطوع حركة الآخِر للوقف، فلا يقف بالتحريك؛ لأنَّ العربَ لا تقفُ على متحرِّك. واتفق الفقهاء على أنَّ صفةَ الجزم أن يقف المؤذن عند نهاية كلِّ جملة من جمل الأذان بتسكين الحرف الأخير من الجملة، ولا يصل الجملة بالتي بعدها، إلا جمل التكبير، فاختلفوا هل يصل التكبيرتين بنَفَسٍ واحدٍ ثم يقف، أو يفصل كل تكبيرة على حِدة، وكلتا الصفتين مشروعة.', '', '', 'أو «الله أكبر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1535, 9, 4, 'ثُمَّ يُرَجِّعُ، فيقول بخفض صوت:', 0, 'صفة الأذان. (ص81)

حاشية: وهذا الترجيع في الأذان يأتي به المؤذِّنُ تارةً، ويتركه تارةً؛ لأنَّ كُلًّا من الفعل والترك قد ثبتَ في السُّنَّة، وانظر: «الاستذكار» لابن عبد البر (٤/ ١٦)، و«مجموع الفتاوى» (٢٢/ ٦٦، ٦٧).', '', '', 'ثم يرجع فيقول بخفض صوت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1536, 9, 5, '«أشهدُ أن لا إله إلا الله، أشهدُ أن لا إله إلا الله، أشهدُ أنَّ محمدًا رسولُ الله، أشهدُ أنَّ محمدًا رسولُ الله»', 1, 'صفة الأذان. (ص81)', '', '', '«أشهد أن لا إله إلا الله أشهد أن لا إله إلا الله أشهد أن محمدا رسول الله أشهد أن محمدا رسول الله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1537, 9, 6, 'ثُمَّ يُعيدُهما برفع الصوت، ثم يقول:', 0, 'صفة الأذان. (ص81)', '', '', 'ثم يعيدهما برفع الصوت ثم يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1538, 9, 7, '«حَيَّ على الصلاة، حيَّ على الصلاة، حيَّ على الفلاح، حَيَّ على الفلاح، الله أكبر، الله أكبر، لا إله إلا الله»', 1, 'صفة الأذان. (ص81)', '', '', '«حي على الصلاة حي على الصلاة حي على الفلاح حي على الفلاح الله أكبر الله أكبر لا إله إلا الله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1539, 9, 8, 'يقول بعد الفلاح:', 0, 'التثويب في أذان الفجر. (ص82)

حاشية: اختُلِفَ في التثويب: أيُشرَع في الأذان الأول للفجر أم الثاني؟ والأقرب أنه في الأذان الثاني، وفي الأمر سَعَة، ولا يُنْكَرُ فيه على من جعله في الأول أو الثاني أو فيهما، انظر: «الدرر السنية» (٤/ ٢٠٧–٢١٠)، و«الشرح الممتع» (٢/ ٦١–٦٤).', '', '', 'يقول بعد الفلاح', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (83, 9, 9, '«الصلاةُ خيرٌ من النَّومِ، الصَّلَاةُ خيرٌ من النَّومِ»', 1, 'التثويب في أذان الفجر. (ص82)

حاشية: أمَّا سامع الأذان فيحكي التثويبَ نفسَه، ولا يبدله بغيره؛ لقول رسول الله ﷺ: «إذا سَمِعتُم النداءَ فقولوا مثلَ ما يقول المؤذن» [متفق عليه]، إلا ما ثبت استثناؤه وإبدالُه بالحولقة، وهنا لم يرد استثناء، فيبقى على الأصل، ويقول: «الصلاة خيرٌ من النوم».', '', '', '«الصلاة خير من النوم الصلاة خير من النوم»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1540, 9, 10, 'يُشْرَعُ للمؤذِّنِ أن يقولَ بعدَ فراغِه من الأذان:', 0, 'الأذان في الليلة المطيرة أو الشديدةِ الرِّيحِ أو البَرْدِ. (ص83)

حاشية: هذا أولى الأقوال؛ لأنَّ فيه بقاءَ نَظْمِ الأذان على وضعه متصلًا، وقال بعضُ العلماء: تُقال في أثناء الأذان بدلًا من الحيعلة، وقال آخرون: تُقال في أثناء الأذان ولكن بعد الحيعلة (أي أنه يجمع بينها وبين الحيعلة)، وقال آخرون: الأمرُ واسِعٌ، فله أن يقولَها أثناء الأذان، أو بعد الفراغ منه، وكل ذلك ثبت في السنة، ولا منافاة بينها لأنَّ أحدها جرى في وقتٍ، والآخَر في وقتٍ آخر، والكل صحيح، وانظر: «شرح النووي» (٥/ ٢٠٧).
ولا تناقض في حالة إتيان المؤذن بقوله: «حيَّ على الصلاة» مع قوله: «الصلاة في الرحال»؛ لأنَّ معنى «الصلاة في الرحال» أنها رخصة لِمَنْ أراد أن يترخَّصَ، ومعنى «حيَّ على الصلاة»: «هَلُمُّوا إلى الصلاة»، أي أنَّ صلاتها في المسجد ندبٌ لِمَنْ أرادَ أن يستكملَ الفضيلة، ولو تحمَّل المشقة، ويؤيد ذلك حديثُ جابر رضي الله عنه: خرجنا مع رسول الله ﷺ في سفرٍ فَمُطِرْنا، فقال: «لِيُصَلِّ من شاء منكم في رَحْلِه». رواه مسلم (٦٩٨).', '', '', 'يشرع للمؤذن أن يقول بعد فراغه من الأذان', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (84, 9, 11, 'صَلُّوا في بيوتكم', 1, 'الأذان في الليلة المطيرة أو الشديدةِ الرِّيحِ أو البَرْدِ. (ص83)', '', '', 'صلوا في بيوتكم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (85, 9, 12, 'أو: ألا صَلُّوا في رِحالكم', 1, 'الأذان في الليلة المطيرة أو الشديدةِ الرِّيحِ أو البَرْدِ. (ص84)

حاشية: وثبت بلفظ: «ألا صَلُّوا في الرحال»، و«صلوا في رحالكم»، و«الصلاة في الرِّحال».
الرِّحال: جمع رَحْل، وهو مسكن الرجل وما فيه من أثاثه.', '', '', 'أو ألا صلوا في رحالكم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (898, 9, 13, 'أو: ومن قَعَدَ فلا حَرَجَ', 1, 'الأذان في الليلة المطيرة أو الشديدةِ الرِّيحِ أو البَرْدِ. (ص84)', '', '', 'أو ومن قعد فلا حرج', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1541, 9, 14, 'يَحْدُرُ المقيمُ في إقامته حَدْرًا، بأن يُسْرِعَ فيها مع بيان حروفها وكلماتها، ووَصْلِ بعضها ببعضٍ بلا فصلٍ بينها، فيقول:', 0, 'صفة الإقامة. (ص85)', '', '', 'يحدر المقيم في إقامته حدرا بأن يسرع فيها مع بيان حروفها وكلماتها ووصل بعضها ببعض بلا فصل بينها فيقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (899, 9, 15, 'اللهُ أكبرَ، اللهُ أكبر،
أشهدُ أن لا إله إلا الله، أشهدُ أنَّ محمدًا رسولُ الله،
حيَّ على الصلاةِ، حيَّ على الفلاحِ،
قد قامتِ الصلاةُ، قد قامتِ الصلاة،
اللهُ أكبرَ، اللهُ أكبرْ،
لا إلهَ إلَّا الله', 1, 'صفة الإقامة. (ص85–86)

حاشية: اختلفوا في ألفاظ الإقامة:
- فقال بعضهم: إنَّ ألفاظَها مفردة ما عدا التكبير في أولها وآخرها، وقول المقيم: «قد قامت الصلاة»، فهو مثنى.
- وقال بعضهم: إنَّ ألفاظَها مُثَنًّى، فيكون التكبير في أولها أربعًا، وبقية ألفاظها مثنى، ما عدا قول: «لا إله إلا الله».
وكلا القولين صحيح؛ حيث ثبتت أحاديث الإفراد وأحاديث التثنية، والاختلاف بينهما محمولٌ عى الإباحة والتخيير، وإلى هذا ذهب الإمام أحمد، وإسحاق بن راهويه، وابن حبَّان، وابن خزيمة، وابن جرير، وداود، وهو اختيارُ شيخِ الإسلام ابنِ تيميَّةَ، وابنِ القيِّم، والصنعاني، والشوكاني، انظر: «الاستذكار» لابن عبد البر (٤/ ١٦)، و«مجموع الفتاوى» (٢٢/ ٦٦، ٦٧).', '', '', 'الله أكبر الله أكبر أشهد أن لا إله إلا الله أشهد أن محمدا رسول الله حي على الصلاة حي على الفلاح قد قامت الصلاة قد قامت الصلاة الله أكبر الله أكبر لا إله إلا الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (900, 9, 16, 'يُستحبُّ لِمَنْ سَمِعَ الأذانَ أن لا يتكلم، ولا يشتغل بقراءة القرآن الكريم، ولا بشيءٍ من الأعمال سوى إجابة المؤذن بأنْ يقول مِن قلبِهِ ما يقول المؤذِّنُ، إلا عند قوله: «حيَّ على الصلاة»، «حيَّ على الفلاح»؛ فإنَّه يقولُ بعدَ كُلٍّ منهما:', 0, 'ما يقول إذا سمع المؤذن. (ص86–87)

حاشية: وطريق القول المروي أن يقول كل كلمة عقب فراغ المؤذن منها مساوقة، لا أن يقولَ الكل بعد فراغ الأذان.
تنبيه: ذهب بعضُ الفقهاء إلى أنَّ سامِع الإقامة يرددها، واستدلوا بأنَّ الإقامةَ أذان لغة وشرعًا، قال ﷺ: «بين كل أذَانَيْنِ صلاة»، وفي الحديث: «إذا سمعتم النداء فقولوا مثلَ ما يقولُ المؤذن» [متفق عليه]. قال الحافظ: «استُدِلَّ به على مشروعية إجابة المؤذِّن في الإقامة، قالوا: إلا في كلمتَيِ الإقامة، فيقول: «أقامها الله وأدامها».اهـ. من «الفتح» (٢/ ٤١٧).
وأُجيب بأنَّ الأصل في النداء أنه يطلق على الأذان خاصَّة، ولا يُطلق على الإقامة إلا بقرينة، كما في قوله ﷺ: «بين كل أذانين صلاة»، ولا قرينة هنا، ولا يُعرَفُ دليلٌ صريحٌ على أنَّ مَنْ سَمِع الإقامة يجيب المقيم.
وأمَّا ما رُوِيَ من أنَّ بلالًا رضي الله عنه أخذ في الإقامة، فلما أنْ قال: «قد قامت الصلاة»، قال النبي ﷺ: «أقامها الله وأدامها»، فإنَّ فيه مجهولًا وضعيفين، ولذلك ضعَّفَه البيهقي، والنووي، وابن حجر، وكذلك الألباني الذي جزم بأنه لا يجوزُ العملُ بهذا الحديث الضعيف؛ «لأنه مخالِفٌ لعموم قوله ﷺ: (فقولوا مثل ما يقول)، فالواجب البقاء مع عمومه، فنقول في الإقامة: (قد قامت الصلاة)، فتأمَّلْ».اهـ. من «التعليق على مشكاة المصابيح» (١/ ٢١٢)، وانظر: «تمام المنة» (ص١٤٩، ١٥٠)، و«ضعيف سنن أبي داود» (ص٢٥٨، ٢٥٩).', '', '', 'يستحب لمن سمع الأذان أن لا يتكلم ولا يشتغل بقراءة القرآن الكريم ولا بشيء من الأعمال سوى إجابة المؤذن بأن يقول من قلبه ما يقول المؤذن إلا عند قوله «حي على الصلاة» «حي على الفلاح» فإنه يقول بعد كل منهما', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (901, 9, 17, '«لا حولَ ولا قُوَّةَ إلَّا باللهِ»', 1, 'ما يقول إذا سمع المؤذن. (ص87)

حاشية: مقصود الحيعلة الدعاء إلى الصلاة، وذلك يحصل من المؤذن، فَعُوِّضَ سامعُه عما يفوته من ثواب الحيعلة بثواب الحولقة التي هي استعانة بالله على أداء الصلاة التي دُعِيَ إليها بقول المؤذن: «حَيَّ على الصلاة، حَيَّ على الفلاح»، أي: هَلُمُّوا إلى الصلاة، وأقبِلوا على سبب البقاء في الجنة.
قال الطيبي: «معنى الحيعلتين: هَلُمَّ بوجهك وسريرتك إلى الهُدَى عاجلًا، والفوزِ بالنعيم آجلًا، فناسَبَ أن يقول: هذا أمرٌ عظيمٌ لا أستطيعُ –مع ضعفي– القيامَ به إلا إذا وَفَّقَني اللهُ بحولِه وقوَّتِه».اهـ. نقلًا من «فتح الباري» (٢/ ٤١٦).', '', '', '«لا حول ولا قوة إلا بالله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1542, 9, 18, 'ويجوز له أن يقتصرَ أحيانًا على إجابة قول المؤذِّن: «أشهدُ أن لا إله إلا الله، أشهدُ أنَّ محمدًا رسولُ الله» بقوله:', 0, 'ما يقول إذا سمع المؤذن. (ص88)', '', '', 'ويجوز له أن يقتصر أحيانا على إجابة قول المؤذن «أشهد أن لا إله إلا الله أشهد أن محمدا رسول الله» بقوله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (902, 9, 19, '«وأنا، وأنا»', 1, 'ما يقول إذا سمع المؤذن. (ص88)', '', '', '«وأنا وأنا»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1543, 9, 20, 'فإذا سَمِعَ التَّشهُّدَ الأخيرَ للمؤذِّنِ، قال:', 0, 'ما يقول إذا سمع المؤذن. (ص88)', '', '', 'فإذا سمع التشهد الأخير للمؤذن قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (903, 9, 21, 'وأنا أشهدُ أن لا إله إلا الله وحدَهُ، لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُهُ ورسولُه، رَضِيتُ باللهِ ربًّا، وبمحمدٍ رسولًا، وبالإسلامِ دينًا', 1, 'ما يقول إذا سمع المؤذن. (ص88)', '', '', 'وأنا أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله رضيت بالله ربا وبمحمد رسولا وبالإسلام دينا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (904, 9, 22, 'ثُمَّ يُصَلِّي ويُسَلِّم على النبي ﷺ.', 0, 'ما يقول إذا سمع المؤذن. (ص88)

حاشية: انظر: (ص١٠٩).', '', '', 'ثم يصلي ويسلم على النبي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1544, 9, 23, 'ثم يقول:', 0, 'ما يقول إذا سمع المؤذن. (ص88)', '', '', 'ثم يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (905, 9, 24, 'اللهم رَبَّ هذه الدعوةِ التَّامَّةِ، والصلاةِ القائمةِ، آتِ محمدًا الوسيلةَ والفضيلةَ، وابْعَثْهُ مَقامًا محمودًا الذي وَعَدْتَهُ', 1, 'ما يقول إذا سمع المؤذن. (ص88)', '', '', 'اللهم رب هذه الدعوة التامة والصلاة القائمة آت محمدا الوسيلة والفضيلة وابعثه مقاما محمودا الذي وعدته', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (906, 9, 25, 'ويُكْثِرُ الدُّعاءَ بين الأذانِ والإقامةِ؛ لقول رسول الله ﷺ: «الدُّعاءُ بين الأذانِ والإقامةِ مُستجابٌ، فادْعُوا».', 0, 'ما يقول إذا سمع المؤذن. (ص88)', '', '', 'ويكثر الدعاء بين الأذان والإقامة لقول رسول الله «الدعاء بين الأذان والإقامة مستجاب فادعوا»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1545, 9, 26, 'وقال رجلٌ: يا رسولَ الله، إنَّ المؤذِّنين يَفْضُلوننا، فقال ﷺ: «قُل كما يقولون، فإذا انتهيتَ؛ فَسَلْ تُعْطَهُ».', 0, 'ما يقول إذا سمع المؤذن. (ص89)', '', '', 'وقال رجل يا رسول الله إن المؤذنين يفضلوننا فقال «قل كما يقولون فإذا انتهيت فسل تعطه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1015, 114, 1, 'سَوُّوا صُفُوفَكُمْ؛ فإنَّ تسويةَ الصُّفوفِ من إقامةِ الصلاة.', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص89)', '', '', 'سووا صفوفكم فإن تسوية الصفوف من إقامة الصلاة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1546, 114, 2, 'أو أيًّا من الوصايا التالية:', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص89)', '', '', 'أو أيا من الوصايا التالية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1016, 114, 3, 'لَتُسَوُّنَّ صُفُوفَكم، أو لَيُخَالِفَنَّ اللهُ بينَ وُجُوهِكُم.', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص89)', '', '', 'لتسون صفوفكم أو ليخالفن الله بين وجوهكم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1017, 114, 4, 'اِسْتَوُوا، اِسْتَوُوا، اِسْتَوُوا.', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص89)', '', '', 'استووا استووا استووا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1018, 114, 5, 'اِسْتَوُوا، ولا تختلِفوا فتخْتَلِفَ قلوبُكم، لِيَلِيَنِي منكم أولو الأحلامِ والنُّهى، ثُمَّ الذين يَلُونَهم، ثُمَّ الذين يَلُونَهم.', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص89)', '', '', 'استووا ولا تختلفوا فتختلف قلوبكم ليليني منكم أولو الأحلام والنهى ثم الذين يلونهم ثم الذين يلونهم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1019, 114, 6, 'رُصُّوا صفوفَكم، وقاربوا بينها، وحاذُوا بالأعناق.', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص89)', '', '', 'رصوا صفوفكم وقاربوا بينها وحاذوا بالأعناق', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1020, 114, 7, 'أتِمُّوا الصَّفَّ المُقَدَّمَ، ثُمَّ الذي يَلِيه، فما كان من نَقْصٍ فَلْيَكُن في الصَّفِّ المؤخَّرِ.', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص89)', '', '', 'أتموا الصف المقدم ثم الذي يليه فما كان من نقص فليكن في الصف المؤخر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1021, 114, 8, 'أقيموا الصفوفَ، وحاذُوا بينَ المناكِبِ، وسُدُّوا الخَلَلَ، وَلِينوا بأيدي إخوانِكم، ولا تَذَروا فُرُجاتٍ للشيطانِ، ومن وَصَلَ صَفًّا وَصَلَه الله، ومن قَطَعَ صَفًّا قطعه الله.', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص90)', '', '', 'أقيموا الصفوف وحاذوا بين المناكب وسدوا الخلل ولينوا بأيدي إخوانكم ولا تذروا فرجات للشيطان ومن وصل صفا وصله الله ومن قطع صفا قطعه الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1022, 114, 9, 'ولا بأسَ أن يقولَ للمصلِّين أحيانًا: «صَلُّوا صلاةَ مُوَدِّعٍ».', 0, 'ما يقول الإمام للمصلين بين يدي الصلاة. (ص90)', '', '', 'ولا بأس أن يقول للمصلين أحيانا «صلوا صلاة مودع»', '', '');

